import Foundation

let generatedHeader = """
    // Generated by scream-generate from flecs.h. Do not edit by hand.
    // Run `swift run scream-generate` after moving the Flecs submodule to a new release.

    """

/// Flecs' C enums as Swift enums with Flecs' numeric values.
func emitEnums(_ api: API) -> String {
    var out = generatedHeader
    for enumeration in api.enums {
        out += "\n"
        out += emitEnum(enumeration)
    }
    return out
}

private func emitEnum(_ enumeration: API.Enum) -> String {
    let name = swiftEnumName(enumeration.cName)
    // Flecs ends some enums with a `...Last = <alias>` marker; Swift enums cannot repeat a value,
    // and the marker would also hide the prefix the real constants share.
    var seen: Set<Int> = []
    let constants = enumeration.constants.filter { seen.insert($0.value).inserted }
    let prefix = commonPrefix(of: constants.map(\.cName))
    var out = docComment(enumeration.documentation, fallback: "Flecs' `\(enumeration.cName)`.")
    out += "public enum \(name): Int32, Sendable, CaseIterable {\n"
    for constant in constants {
        out += docComment(constant.documentation, fallback: "Flecs' `\(constant.cName)`.", indent: "    ")
        out += "    case \(swiftCaseName(constant.cName, prefix: prefix)) = \(constant.value)\n"
    }
    out += "}\n"
    return out
}

/// Flecs' builtin entities, tags, relationships and phases as static members of `Entity`.
func emitBuiltins(_ api: API) -> String {
    var out = generatedHeader
    out += "\nimport CFlecs\n\nextension Entity {\n"
    var first = true
    for builtin in api.builtins {
        if !first {
            out += "\n"
        }
        first = false
        out += docComment(builtin.documentation, fallback: "Flecs' `\(builtin.cName)`.", indent: "    ")
        let name = swiftBuiltinName(builtin.cName)
        out += "    public static var \(name): Entity { Entity(rawValue: \(builtin.cName)) }\n"
    }
    out += "}\n"
    return out
}

/// Parses wrapped.txt into a map from C function name to Swift symbol.
///
/// One line per wrapped Flecs function: the C name, whitespace, then the Swift symbol. Lines
/// starting with `#` are comments.
func parseWrapped(_ text: String, api: API) throws -> [String: String] {
    let known = Set(api.functions.map(\.name))
    var wrapped: [String: String] = [:]
    for (number, rawLine) in text.split(separator: "\n", omittingEmptySubsequences: false).enumerated() {
        let line = rawLine.trimmingCharacters(in: .whitespaces)
        guard !line.isEmpty, !line.hasPrefix("#") else { continue }
        guard let space = line.firstIndex(where: \.isWhitespace) else {
            throw GenerateError("wrapped.txt:\(number + 1): expected '<C function> <Swift symbol>'")
        }
        let cName = String(line[..<space])
        let swift = line[space...].trimmingCharacters(in: .whitespaces)
        guard known.contains(cName) else {
            throw GenerateError("wrapped.txt:\(number + 1): \(cName) is not a Flecs function")
        }
        wrapped[cName] = swift
    }
    return wrapped
}

/// The API Coverage article: every Flecs function under its Doxygen group, with its Swift symbol.
func emitCoverage(_ api: API, wrapped: [String: String], version: String) throws -> String {
    var sections: [(title: String, functions: [API.Function])] = []
    var groupIndex = 0
    for function in api.functions {
        while groupIndex + 1 < api.groups.count, api.groups[groupIndex + 1].line < function.line {
            groupIndex += 1
        }
        guard groupIndex < api.groups.count, api.groups[groupIndex].line < function.line else {
            throw GenerateError("\(function.name) comes before the first @defgroup")
        }
        let title = api.groups[groupIndex].title
        if let index = sections.firstIndex(where: { $0.title == title }) {
            sections[index].functions.append(function)
        } else {
            sections.append((title, [function]))
        }
    }

    let total = api.functions.count
    let done = api.functions.filter { wrapped[$0.name] != nil }.count
    var out = """
        # API Coverage

        Which Flecs \(version) functions Scream wraps, and where.

        ## Overview

        This page is generated by `swift run scream-generate` from the declarations in `flecs.h` and
        `Tools/Generate/wrapped.txt`. \(done) of \(total) functions are wrapped. The sections are
        Flecs' own Doxygen groups. Function-like macros such as `ecs_pair` and `ECS_COMPONENT` are
        not functions and do not appear; Scream covers them through `CFlecsShims` and generics.


        """
    for section in sections {
        let count = section.functions.filter { wrapped[$0.name] != nil }.count
        out += "## \(section.title) (\(count) of \(section.functions.count))\n\n"
        out += "| Flecs | Scream |\n| --- | --- |\n"
        for function in section.functions {
            let swift = wrapped[function.name].map { "`\($0)`" } ?? "not yet"
            out += "| `\(function.name)` | \(swift) |\n"
        }
        out += "\n"
    }
    return out
}
